111	impl TransformerBlock35 {
112	    /// Load one decoder block: `prefix` is the layer's tensor prefix (e.g.
113	    /// `model.language_model.layers.3`).
114	    pub(super) fn load(src: &WeightSource, prefix: &str, layer_type: LayerType) -> Result<Self> {
115	        let attn = match layer_type {
116	            LayerType::FullAttention => LayerKind::FullAttention(FullAttentionLayer::load(
117	                src,
118	                &format!("{prefix}.self_attn"),
119	            )?),
120	            LayerType::LinearAttention => LayerKind::LinearAttention(LinearAttentionLayer::load(
121	                src,
122	                &format!("{prefix}.linear_attn"),
123	            )?),
124	        };
125	        Ok(Self {
126	            input_layernorm: src.tensor_1d(&format!("{prefix}.input_layernorm.weight"))?,
127	            attn,
