303	    fn rejects_indivisible_dense_dimensions() {
304	        let tp = TensorParallelConfig::try_from((0, 3)).unwrap();
305	        let cfg = config();
306	        let mut err = LocalGeometry::try_new(&cfg, tp).unwrap_err();
307	        assert_eq!(
308	            err,
309	            ConfigError::TpIndivisible {
310	                field: "num_attention_heads",
311	                value: 16,
312	                world_size: 3,
313	            }
