320	        assert_eq!(
321	            err,
322	            ConfigError::TpIndivisible {
323	                field: "num_key_value_heads",
324	                value: 4,
325	                world_size: 3,
326	            }
327	        );
328	
329	        broken.num_key_value_heads = 3;
330	        broken.intermediate_size = 9217;
331	        err = LocalGeometry::try_new(&broken, tp).unwrap_err();
332	        assert_eq!(
333	            err,
334	            ConfigError::TpIndivisible {
335	                field: "intermediate_size",
336	                value: 9217,
337	                world_size: 3,
338	            }
339	        );
340	    }
341	
342	    #[test]
343	    fn requires_linear_attention_key_head_divisibility() {
344	        let tp = TensorParallelConfig::try_from((1, 2)).unwrap();
345	        let mut broken = config();
346	        // Keep the Config35 value % key invariant intact so the failing
347	        // branch is the key-head TP guard itself.
348	        broken.linear_num_key_heads = 17;
349	        broken.linear_num_value_heads = 34;
350	        let err = LocalGeometry::try_new(&broken, tp).unwrap_err();
351	        assert_eq!(
352	            err,
353	            ConfigError::TpIndivisible {
354	                field: "linear_num_key_heads",
355	                value: 17,
356	                world_size: 2,
357	            }
358	        );
359	    }
