1	//! Qwen3.5 wrappers: the HD256 full-attention decode prep and paged attention
2	//! reads, and the Gated DeltaNet decode step over
3	//! `csrc/qwen35/{gated_delta_rule,conv1d}.cu`.
4	
5	use anyhow::Context as _;
6	use anyhow::Result;
7	use cudarc::driver::CudaSlice;
8	use cudarc::driver::DevicePtr;
9	use cudarc::driver::DevicePtrMut;
10	use half::bf16;
11	
12	use super::PrefillPagedPlan;
13	use super::attention::PagedGeometry;
14	use super::attention::checked_paged_geometry;
15	use crate::ffi;
16	use crate::paged_kv::PagedKvLayout;
17	use crate::tensor::Columns;
18	use crate::tensor::DeviceContext;
19	use crate::tensor::DeviceVec;
20	use crate::tensor::HiddenStates;
21	
22	/// Batched QK RMSNorm + partial RoPE for Qwen3.5 HD256 decode.
23	///
24	/// Reads Q from interleaved `q_full` ([q, gate] per head), writes prepared Q into `q`,
25	/// and normalizes/applies partial RoPE to `k` in-place using per-request positions.
26	#[allow(clippy::too_many_arguments)]
27	pub fn qk_norm_partial_rope_batched_decode_hd256_into(
28	    ctx: &DeviceContext,
29	    q_full: &HiddenStates,
30	    q: &mut HiddenStates,
31	    k: &mut HiddenStates,
32	    q_norm_weight: &DeviceVec,
33	    k_norm_weight: &DeviceVec,
34	    cos_cache: &DeviceVec,
35	    sin_cache: &DeviceVec,
36	    positions_d: &CudaSlice<i32>,
37	    num_q_heads: usize,
38	    num_kv_heads: usize,
39	    rotary_dim: usize,
40	    rms_eps: f32,
41	) {
42	    let batch_size = q.seq_len;
43	    debug_assert_eq!(q_full.seq_len, batch_size);
44	    debug_assert_eq!(k.seq_len, batch_size);
45	
46	    let (qf_ptr, _gqf) = q_full.data.device_ptr(&ctx.stream);
47	    let (q_ptr, _gq) = q.data.device_ptr_mut(&ctx.stream);
48	    let (k_ptr, _gk) = k.data.device_ptr_mut(&ctx.stream);
49	    let (qn_ptr, _gqn) = q_norm_weight.data.device_ptr(&ctx.stream);
50	    let (kn_ptr, _gkn) = k_norm_weight.data.device_ptr(&ctx.stream);
51	    let (cos_ptr, _gc) = cos_cache.data.device_ptr(&ctx.stream);
52	    let (sin_ptr, _gs) = sin_cache.data.device_ptr(&ctx.stream);
53	    let (pos_ptr, _gp) = positions_d.device_ptr(&ctx.stream);
54	
55	    unsafe {
56	        ffi::qk_norm_partial_rope_batched_decode_hd256_cuda(
57	            qf_ptr as *const ffi::Half,
58	            k_ptr as *mut ffi::Half,
59	            qn_ptr as *const ffi::Half,
60	            kn_ptr as *const ffi::Half,
61	            cos_ptr as *const ffi::Half,
